use std::collections::HashMap;
use std::rc::Rc;
use std::cell::RefCell;

pub struct Cache {
    inner: Rc<RefCell<HashMap<String, String>>>,
}

impl Cache {
    pub fn get(&self, k: &str) -> Option<String> {
        self.inner.borrow().get(k).cloned()
    }
}

